local _, WFJ = ...
WFJ.Data.add("book", {
  ["1d0a5c74c98451a0"] = { "Braccato senza sosta dagli umani, Hellscream conservava comunque l'inestinguibile volontà di combattere dell'⟦Horde=Orda⟧. Con il solo aiuto del suo devoto clan ⟦Warsong=Cantaguerra⟧, Hellscream continuava a condurre una guerra clandestina contro l'oppressione del suo popolo assediato. Purtroppo Hellscream non riuscì mai a trovare il modo di risvegliare gli orchi prigionieri dal loro torpore. L'impressionabile Thrall, ispirato dagli ideali di Hellscream, sviluppò una forte affinità con l'⟦Horde=Orda⟧ e con le sue tradizioni guerriere.", "." },
  ["1d2a3e350f781068"] = { "Mentre l'occhio destro splendeva sull'alba dorata, le mani gentili della Madre Terra si stesero sulle pianure dorate. Ovunque passasse l'ombra delle sue braccia, dal suolo fertile sorgeva un popolo nobile. Gli Shu'halo (i tauren) sorsero per rendere grazie e pregare la loro madre amorevole. Là, nei campi infiniti dell'alba, i figli della terra si consacrarono alla sua grazia e giurarono di benedirne il nome fino all'ultimo oscurarsi del mondo.", "." },
  ["1d4a637158139edc"] = { "Tempo fa, al quartier generale della ⟦Explorers' League=Lega degli Esploratori⟧ a ⟦Ironforge=Forgiardente⟧, ricordo una lezione tenuta dall'archeologo capo Greywhisker. Il vecchio parlò di un dio del genere, venerato dagli strani elfi di Darnassus per la sua presunta natura altruista--\n\nBah! Un momento. Sento grugnire fuori dalla tenda. Di sicuro sono solo dei Thistle Boar che cercano di arrivare alla mia scorta di mele....", "." },
  ["1d7efb7b2219d2d0"] = { "La ⟦Venture Company=S.P.R. & Co.⟧ <testo illeggibile> Sembrerebbe che quegli sciocchi abbiano quasi spazzato via la loro intera operazione nel tentativo di stabilizzare la miscela.\n\n<diverse pagine sembrano strappate>", "." },
  ["1d8168c357673675"] = { "Wyrmthalak, ho ricevuto ordini diretti dal tuo padrone, Nefarian, di punirti come riterrò opportuno se altri estranei riusciranno a entrare nella cittadella. Non dimenticare chi ti comanda, rettile. Il figlio di Blackhand: maestro della lama e della battaglia. L'unico vero Capoguerra. -Rend", "." },
  ["1de6b79faab6d1be"] = { "Le epiche battaglie della Seconda Guerra spaziarono da grandi scontri navali a immensi duelli nei cieli. In qualche modo l'⟦Horde=Orda⟧ aveva portato alla luce un potente manufatto noto come Demon Soul, e lo aveva usato per rendere schiava l'antica Regina dei Draghi, Alexstrasza. Minacciando di distruggere le sue preziose uova, l'⟦Horde=Orda⟧ costrinse Alexstrasza a mandare in guerra i suoi figli adulti. I nobili draghi rossi furono costretti a combattere per l'⟦Horde=Orda⟧, e combatterono davvero.", "." },
  ["1df03ddb3c5c8b82"] = { "Il goblin Nazz Steamboil è in realtà il figlio di un principe mercante goblin (quale principe? Il prezzo di questa informazione è alto).\n\nSembra che gli piaccia molto di più spendere i soldi che guadagna la sua famiglia che guadagnarli da sé. Così ha rubato una piccola fortuna dal tesoro di famiglia e ora si nasconde nelle Distese Salate.\n\nSe suo padre sapesse dov'è, andrebbe di sicuro a cercarlo e lo trascinerebbe a casa... con un dito del piede in meno per la sua insolenza.", "." },
})
